head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vListTypeCd = '';
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_1);
        // 파라미터설정
        scwin.setParam();
        // 회사명 포커스
        txb_IsuNm.focus();
        if (txb_IsurNm.getValue() !== '' ||
            txb_IsuNm.getValue() !== '') {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25101.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.setParReturn();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurNm_onkeypress
 * @description txb_IsurNm onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_IsurNm_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.txb_IsurNm_onkeypress" });
    }
};

/**
 * @method
 * @name txb_IsuNm_onkeypress
 * @description txb_IsuNm onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_IsuNm_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25101.txb_IsuNm_onkeypress" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
// null전체,1상장,2상장/상장폐지

/**
 * @method
 * @name search
 * @description 상장종목 데이터를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (txb_IsuNm.getValue() === '' && txb_IsurNm.getValue() === '') {
        await $c.win.alert('검색조건을 입력하십시오.');
        txb_IsuNm.focus();
        return;
    }
    let param = '';
    param += "&{P}V_ISUR_NM=" + txb_IsurNm.getValue();
    param += "&{P}V_ISU_NM=" + txb_IsuNm.getValue();
    param += "&{P}V_LIST_TYPE_CD=" + scwin.vListTypeCd;
    const dsNm = 'BNS_LIST_BND_POP';
    const qryId = 'lds.stf.bnslistcrchl.select.listListBndIsu';
    $c.bns.fn_SearchBns("ULDBNS25101.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        if (typeof(arrPar[0].LIST_TYPE_CD) !== 'undefined') {
            scwin.vListTypeCd = arrPar[0].LIST_TYPE_CD;
        }
        if (typeof(arrPar[0].ISUR_NM) !== 'undefined') {
            txb_IsurNm.setValue(arrPar[0].ISUR_NM);
        }
        if (typeof(arrPar[0].ISU_NM) !== 'undefined') {
            txb_IsuNm.setValue(arrPar[0].ISU_NM);
        }
    }
};

/**
 * @method
 * @name setParReturn
 * @description 부모창에 보낼 데이터를 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParReturn = async function() {
    let arrPar = new Array();
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        ISU_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISU_NM"),
        ISUR_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_NM")
    };
    scwin.fn_SetPar(arrPar);
    await $c.win.closePopup();
};
